"""Write docs/evidence/v14_results.md from the judged v14 outputs (file reading only; every number comes from a RESULT.json or gate table).
usage: python docs/evidence/v14_collect.py <kaggle_dir> <out.md>
expects under <kaggle_dir>: judged_v14_seed{71,72,73}/ (gate tables + VERDICT.json), judged_v14_esci_seed{55,71,72,73}/RESULT.json, judged_v14_port_{fiqa,nq}/RESULT.json, v14_seed_rule.json"""
import json, os, sys

K, OUT = sys.argv[1], sys.argv[2]
ld = lambda *p: json.load(open(os.path.join(K, *p))) if os.path.exists(os.path.join(K, *p)) else None
f3 = lambda x: '-' if x is None else (f'{x:.3f}' if isinstance(x, (int, float)) and x == x and abs(x) != float('inf') else str(x))
pct = lambda x: '-' if x is None else f'{100 * x:.2f}%'
ci = lambda c: f'[{c[0]:+.3f}, {c[1]:+.3f}]' if c and c[0] == c[0] else '-'
L = ['# v14 results (generated by docs/evidence/v14_collect.py; do not edit by hand)', '', 'Protocol: `docs/evidence/v14_flagship_protocol.md`. Every outcome is listed, pass or fail.', '']

S = ld('v14_seed_rule.json')
L += ['## E1. Untouched seeds 71, 72, 73 (frozen v6 code)', '']
if S:
    J = S['judged_seeds']
    L += ['| Run | Verdict | Detectors | Repairs | L1 clean loss | L2 closure | U1 | N1 (points) |', '|---|---|---|---|---|---|---|---|']
    for r in J['per_run']: L.append(f"| {r['dir']} | {r['verdict']} | {r['detectors']} | {r['repairs']} | {pct(r['L1'])} | {f3(r['L2'])} | {f3(r['U1'])} | {f3(100 * r['N1'] if r['N1'] is not None else None)} |")
    L += ['', f"**R-avg (primary): {J['R_avg']['verdict']}** - detectors {J['R_avg']['detectors_pass']}/28 (failing: {', '.join(J['R_avg']['failing_detectors']) or 'none'}), repairs {J['R_avg']['repairs_pass']}/28 (failing: {', '.join(J['R_avg']['failing_repairs']) or 'none'}).",
          f"**R-maj (secondary): {J['R_maj']['verdict']}** - adopted on {J['R_maj']['adopted_runs']} of {J['R_maj']['of']} seeds.", '',
          '| Detector | AUROC seed 71 / 72 / 73 | mean | pass |', '|---|---|---|---|']
    for f, v in J['detectors'].items():
        if v['mean'] < 0.95 or not v['passed']: L.append(f"| {f} | {' / '.join(f3(a) for a in v['aurocs'])} | {f3(v['mean'])} | {v['passed']} |")
    L.append('(detectors with mean >= 0.95 that pass are omitted from this table; all are in v14_seed_rule.json)')
    if 'descriptive_old_seeds' in S:
        D = S['descriptive_old_seeds']; L += ['', f"Descriptive only (rule written after these were seen): seeds 50, 52, 55 under R-avg: {D['R_avg']['verdict']} (detectors {D['R_avg']['detectors_pass']}/28, failing {', '.join(D['R_avg']['failing_detectors']) or 'none'})."]
else: L.append('not available')
L.append('')

L += ['## E2. Unseen faults: ceiling decomposition, and E2b verify-then-escalate', '']
L += ['| Seed | role | U1 (stored policy) | C_flag (flagged and some reachable repair fixes) | C_any | U1 F_esc | U1 F_keep | U1 F_univ | F_esc - P0 (95% CI over faults) |', '|---|---|---|---|---|---|---|---|---|']
for s in ('55', '71', '72', '73'):
    r = ld(f'judged_v14_esci_seed{s}', 'RESULT.json')
    if not r or not isinstance(r.get('E2'), dict): L.append(f'| {s} | {"dev" if s == "55" else "confirm"} | not available | | | | | | |'); continue
    U = r['E2']; L.append(f"| {s} | {'dev' if s == '55' else 'confirm'} | {f3(U['U1_P0'])} | {f3(U.get('C_flag'))} | {f3(U.get('C_any'))} | {f3(U['U1_F_esc'])} | {f3(U['U1_F_keep'])} | {f3(U['U1_F_univ'])} | {f3(U['F_esc_minus_P0']['mean'])} {ci(U['F_esc_minus_P0']['ci'])} |")
L += ['', '| Seed | policy | held-out clean loss | clean dispatch | clean escalation | clean cost | in-distribution closure |', '|---|---|---|---|---|---|---|']
for s in ('55', '71', '72', '73'):
    r = ld(f'judged_v14_esci_seed{s}', 'RESULT.json')
    if not r: continue
    for p, v in r['E2b_policies'].items(): L.append(f"| {s} | {p} | {pct(v['clean_loss'])} | {pct(v['clean_dispatch'])} | {pct(v['clean_escalation'])} | {f3(v['clean_mean_cost'])} | {f3(v['mean_closure'])} |")
r55 = ld('judged_v14_esci_seed55', 'RESULT.json')
if r55 and 'E2b_selection_rule_output' in r55: L += ['', f"Dev selection (seed 55): primary = **{r55['E2b_selection_rule_output']['primary']}**; dev values {json.dumps(r55['E2b_selection_rule_output']['dev'])}."]
conf = [ld(f'judged_v14_esci_seed{s}', 'RESULT.json') for s in ('71', '72', '73')]
if r55 and all(c and isinstance(c.get('E2'), dict) for c in conf):
    pr = r55['E2b_selection_rule_output']['primary']; u = [c['E2']['U1_' + pr] for c in conf]
    cl = [c['E2b_policies'][f'{pr} mondrian']['clean_loss'] for c in conf]; clo = [c['E2b_policies'][f'{pr} mondrian']['mean_closure'] for c in conf]; base = [c['E2b_policies']['mondrian_crc_0.005 (frozen)']['mean_closure'] for c in conf]
    c1, c2, c3 = sum(u) / 3 >= 0.5, all(x <= 0.005 for x in cl), all(a >= b - 0.02 for a, b in zip(clo, base))
    L += [f"**E2b confirmation ({pr}): {'CONFIRMED' if c1 and c2 and c3 else 'NOT CONFIRMED'}** - mean U1 {sum(u) / 3:.3f} (bar 0.50: {c1}); clean loss per seed {', '.join(pct(x) for x in cl)} (<= 0.5%: {c2}); closure per seed {', '.join(f3(x) for x in clo)} vs base {', '.join(f3(x) for x in base)} (not below base - 0.02: {c3})."]
L.append('')

L += ['## E3. Real failures in ESCI natural traffic, labelled by intervention', '']
for s in ('55', '71', '72', '73'):
    r = ld(f'judged_v14_esci_seed{s}', 'RESULT.json')
    if not r or 'E3' not in r: continue
    E = r['E3']; sr = E['success_on_repairable']; dr = E['detection_repairable_vs_success']; h = E['harm_on_real_successes']
    L += [f"**Seed {s}.** real failures {E['real_failures']} (non-placeholder gold), repairable {E['repairable']} ({pct(E['coverage'])}). Success on repairable: loop {f3(sr['loop'])}, universal {f3(sr['universal'])}, random catalogue repair {f3(sr['random_catalogue_repair'])}, escalation {f3(sr['escalation'])}; loop - random {f3(sr['loop_minus_random']['mean'])} {ci(sr['loop_minus_random']['ci'])}. "
          f"Detection AUROC repairable vs successes: attributor {f3(dr['attributor']['auroc'])} {ci(dr['attributor']['ci'])}, -NQC {f3(dr['qpp_neg_nqc']['auroc'])}, -WIG {f3(dr['qpp_neg_wig']['auroc'])}; all failures: attributor {f3(E['detection_all_failures_vs_success']['attributor']['auroc'])}. "
          f"Harm on {h['n']} real successes: loop {pct(h['loop_rate'])} (Wilson {ci(h['loop_wilson'])}), universal {pct(h['universal_rate'])}. Claims: {json.dumps(E['claims'])}.", '']
    L += ['Labels (repair that restores the failure: count): ' + ', '.join(f'{k}: {v}' for k, v in list(E['label_counts'].items())[:12]), '']

L += ['## E4. The do-no-harm gate on the second stack, and E4b real failures there', '']
for ds in ('fiqa', 'nq'):
    r = ld(f'judged_v14_port_{ds}', 'RESULT.json')
    if not r: L += [f'**{ds}:** not available', '']; continue
    L += [f"**{ds}** (port seed {r['seed']}): calibration n {json.dumps(r['calibration']['n'])}; lambdas {json.dumps(r['calibration']['lambdas'])}; non-ceiling faults {', '.join(r['non_ceiling_faults'])}; top-1 identification on faulted {f3(r['identification_top1_on_faulted'])}; "
          f"median seconds: clean run {f3(r['median_seconds']['clean_run'])}, dispatched repair {f3(r['median_seconds']['dispatched_repair_and_run'])}, universal {f3(r['median_seconds']['universal_and_run'])}. **E4 pass: {r['pass']['E4_PASS']}** ({json.dumps(r['pass'])}).", '',
          '| Policy | clean loss (Wilson 95%) | clean dispatch | repairs per clean query | est. s per clean query | closure | closure, non-ceiling faults |', '|---|---|---|---|---|---|---|']
    for p, v in r['policies'].items(): L.append(f"| {p} | {pct(v['clean_loss'])} {ci(v['clean_loss_wilson'])} | {pct(v['clean_dispatch'])} | {f3(v['repairs_per_clean_query'])} | {f3(v['est_median_seconds_per_clean_query'])} | {f3(v['mean_closure'])} | {f3(v['closure_non_ceiling'])} |")
    E = r['E4b']; sr = E['success_on_repairable']; h = E['harm_on_real_successes']
    L += ['', f"E4b: real failures {E['real_failures']}, repairable {E['repairable']} ({pct(E['coverage'])}); success on repairable: loop {f3(sr['loop_mondrian'])}, universal {f3(sr['universal'])}, random {f3(sr['random_catalogue_repair'])}; loop - random {f3(sr['loop_minus_random']['mean'])} {ci(sr['loop_minus_random']['ci'])}; "
          f"attributor AUROC repairable vs successes {f3(E['detection_repairable_vs_success']['attributor']['auroc'])}; harm on {h['n']} successes: gated {pct(h['mondrian_rate'])}, universal {pct(h['universal_rate'])}. Claims: {json.dumps(E['claims'])}.", '']
L += ['## E5. Frontier arm', '', 'Not run unless the owner supplies a funded key (A4.3 of llm_baselines_plan.md).', '']
open(OUT, 'w').write('\n'.join(L)); print('wrote', OUT, len(L), 'lines')
